INSERT INTO `cms_product` (`id`, `name`, `description`, `price`, `stock`, `category_id`, `product_status`, `image_url`, `create_time`, `update_time`) VALUES ('5061', 'Logitech G Pro X', '本书包括九个项目，内容涵盖机械装配（含虚拟装配）与维修基础知识，典型零部件、常用传动机构及典型机械设备的拆卸、装配和维修技术，失效机械零件修复技术，机械设备故障诊断技术，机械设备精度检测与试车验收技术，机械组件虚拟装配技术等多个方面。通过上述知识点和技能点的学习，使学生初步具备在机械装配和设备维修方面的职业素养。', 69.00, 999, '1011', 1, 'http://118.196.16.103:9000/cloud/2026/04/01/机械维修_20260401223800A007.jpg', '2025-04-12 00:00:00', '2026-04-01 22:38:39');
INSERT INTO `cms_product` (`id`, `name`, `description`, `price`, `stock`, `category_id`, `product_status`, `image_url`, `create_time`, `update_time`) VALUES ('5066', '三体', '刘慈欣创作的系列小说\n《三体》是刘慈欣创作的长篇科幻小说系列，由《三体》《三体2：黑暗森林》《三体3：死神永生》组成，第一部于2006年5月起在《科幻世界》杂志上连载，第二部于2008年5月首次出版，第三部则于2010年11月出版。\n作品讲述了地球人类文明和三体文明的信息交流、生死搏杀及两个文明在宇宙中的兴衰历程。《三体》 …\n其第一部经过刘宇昆翻译后获得了第73届雨果奖最佳长篇小说奖 [1]，第三部英文版获得2017年轨迹奖最佳长篇科幻小说奖。2019年，列入“新中国70年70部长篇小说典藏”。 [50]2022年9月，《三体》入选2021十大年度国家IP。', 138.80, 998, '1937808022062034946', 1, 'http://118.196.16.103:9000/cloud/2026/04/01/OIP-C (2)_20260401223620A005.jpg', '2025-04-12 00:00:00', '2026-04-01 22:36:23');
INSERT INTO `cms_product` (`id`, `name`, `description`, `price`, `stock`, `category_id`, `product_status`, `image_url`, `create_time`, `update_time`) VALUES ('5069', '作物栽培学', '《作物栽培学（第2版）》是由胡立勇、丁艳锋主编，高等教育出版社2019年出版的“十一五”国家级规划教材、“十二五”普通高等教育本科国家级规划教材。该教材可作为农学类专业（包括农学、植保、园艺、农业资源与环境等）学生的专业课或专业基础课教材，其他相关专业学生的选修课教材，以及从事农业科技、管理、教育和培训人员的农业科技用书与拓宽知识领域的参考用书。 [1]', 49.90, 999, '1010', 1, 'http://118.196.16.103:9000/cloud/2026/04/01/作物栽培_20260401224039A008.jpg', '2025-04-12 00:00:00', '2026-04-01 22:41:05');
