INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`) VALUES (1093, '商品', 2, 'com.cloud.cms.controller.backed.CmsProductController.edit()', 'PUT', 1, 'admin', NULL, '/product', '127.0.0.1', '', '{\"description\":\"刘慈欣创作的系列小说\\n《三体》是刘慈欣创作的长篇科幻小说系列，由《三体》《三体2：黑暗森林》《三体3：死神永生》组成，第一部于2006年5月起在《科幻世界》杂志上连载，第二部于2008年5月首次出版，第三部则于2010年11月出版。\\n作品讲述了地球人类文明和三体文明的信息交流、生死搏杀及两个文明在宇宙中的兴衰历程。《三体》 …\\n其第一部经过刘宇昆翻译后获得了第73届雨果奖最佳长篇小说奖 [1]，第三部英文版获得2017年轨迹奖最佳长篇科幻小说奖。2019年，列入“新中国70年70部长篇小说典藏”。 [50]2022年9月，《三体》入选2021十大年度国家IP。\",\"productStatus\":1,\"updateTime\":1775054182800,\"createTime\":1744387200000,\"price\":138.8,\"imageUrl\":\"http://118.196.16.103:9000/cloud/2026/04/01/OIP-C (2)_20260401223620A005.jpg\",\"name\":\"三体\",\"id\":\"5066\",\"stock\":999,\"categoryId\":\"1937808022062034946\"}', '{\"code\":0,\"data\":true,\"msg\":\"操作成功\"}', 0, NULL, '2026-04-01 22:36:21');
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`) VALUES (1094, '商品', 2, 'com.cloud.cms.controller.backed.CmsProductController.edit()', 'PUT', 1, 'admin', NULL, '/product', '127.0.0.1', '', '{\"description\":\"愿你找到你想要的书\",\"productStatus\":1,\"updateTime\":1775054213452,\"createTime\":1744387200000,\"price\":9999999,\"imageUrl\":\"http://118.196.16.103:9000/cloud/2026/04/01/废墟图书馆_20260401223649A006.jpg\",\"name\":\"废墟图书馆\",\"id\":\"5058\",\"stock\":1,\"categoryId\":\"1011\"}', '{\"code\":0,\"data\":true,\"msg\":\"操作成功\"}', 0, NULL, '2026-04-01 22:36:50');
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`) VALUES (1095, '商品', 2, 'com.cloud.cms.controller.backed.CmsProductController.edit()', 'PUT', 1, 'admin', NULL, '/product', '127.0.0.1', '', '{\"description\":\"本书包括九个项目，内容涵盖机械装配（含虚拟装配）与维修基础知识，典型零部件、常用传动机构及典型机械设备的拆卸、装配和维修技术，失效机械零件修复技术，机械设备故障诊断技术，机械设备精度检测与试车验收技术，机械组件虚拟装配技术等多个方面。通过上述知识点和技能点的学习，使学生初步具备在机械装配和设备维修方面的职业素养。\",\"productStatus\":1,\"updateTime\":1775054319305,\"createTime\":1744387200000,\"price\":69,\"imageUrl\":\"http://118.196.16.103:9000/cloud/2026/04/01/机械维修_20260401223800A007.jpg\",\"name\":\"Logitech G Pro X\",\"id\":\"5061\",\"stock\":999,\"categoryId\":\"1011\"}', '{\"code\":0,\"data\":true,\"msg\":\"操作成功\"}', 0, NULL, '2026-04-01 22:38:37');
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`) VALUES (1096, '商品', 2, 'com.cloud.cms.controller.backed.CmsProductController.edit()', 'PUT', 1, 'admin', NULL, '/product', '127.0.0.1', '', '{\"description\":\"《作物栽培学（第2版）》是由胡立勇、丁艳锋主编，高等教育出版社2019年出版的“十一五”国家级规划教材、“十二五”普通高等教育本科国家级规划教材。该教材可作为农学类专业（包括农学、植保、园艺、农业资源与环境等）学生的专业课或专业基础课教材，其他相关专业学生的选修课教材，以及从事农业科技、管理、教育和培训人员的农业科技用书与拓宽知识领域的参考用书。 [1]\",\"productStatus\":1,\"updateTime\":1775054465193,\"createTime\":1744387200000,\"price\":49.9,\"imageUrl\":\"http://118.196.16.103:9000/cloud/2026/04/01/作物栽培_20260401224039A008.jpg\",\"name\":\"作物栽培学\",\"id\":\"5069\",\"stock\":999,\"categoryId\":\"1010\"}', '{\"code\":0,\"data\":true,\"msg\":\"操作成功\"}', 0, NULL, '2026-04-01 22:41:03');
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`) VALUES (1097, '商品', 2, 'com.cloud.cms.controller.backed.CmsProductController.edit()', 'PUT', 1, 'admin', NULL, '/product', '127.0.0.1', '', '{\"description\":\"《物理学与生活》由美国学者W. 托马斯·格瑞福斯与朱莉叶·W. 布罗斯合著，北京大学秦克诚翻译，2015年电子工业出版社出版的物理学通识教材 。该书面向概念性物理课程，旨在通过基础理论阐释自然现象的应用逻辑，构建物理学与日常生活的关联性。\",\"productStatus\":1,\"updateTime\":1775054563717,\"createTime\":1744387200000,\"price\":4999,\"imageUrl\":\"http://118.196.16.103:9000/cloud/2026/04/01/物理_20260401224241A009.jpg\",\"name\":\"物理学与生活\",\"id\":\"5067\",\"stock\":999,\"categoryId\":\"1937808022062034946\"}', '{\"code\":0,\"data\":true,\"msg\":\"操作成功\"}', 0, NULL, '2026-04-01 22:42:43');
