INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`) VALUES (1099, '商品', 2, 'com.cloud.cms.controller.backed.CmsProductController.edit()', 'PUT', 1, 'admin', NULL, '/product', '127.0.0.1', '', '{\"description\":\"《高等数学（第七版）》是由同济大学数学系编写、高等教育出版社出版的“十二五”普通高等教育本科国家级规划教材，适合高等院校工科类各专业学生使用。\",\"productStatus\":1,\"updateTime\":1775054640125,\"createTime\":1744387200000,\"price\":22.3,\"imageUrl\":\"http://118.196.16.103:9000/cloud/2026/04/01/高等数学_20260401224358A010.jpg\",\"name\":\"高等数学\",\"id\":\"5065\",\"stock\":999,\"categoryId\":\"1003\"}', '{\"code\":0,\"data\":true,\"msg\":\"操作成功\"}', 0, NULL, '2026-04-01 22:43:57');
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`) VALUES (1100, '商品', 2, 'com.cloud.cms.controller.backed.CmsProductController.edit()', 'PUT', 1, 'admin', NULL, '/product', '127.0.0.1', '', '{\"description\":\"《堂吉诃德》（又译作《唐·吉诃德》《堂·吉诃德》等，全名为《奇情异想的绅士堂吉诃德·德·拉·曼却》）是西班牙作家塞万提斯·萨维德拉于1605年和1615年分两部分出版的长篇反骑士小说\",\"productStatus\":1,\"updateTime\":1775054742173,\"createTime\":1744387200000,\"price\":45.9,\"imageUrl\":\"http://118.196.16.103:9000/cloud/2026/04/01/唐_20260401224513A011.jpg\",\"name\":\"堂吉诃德\",\"id\":\"5052\",\"stock\":999,\"categoryId\":\"1014\"}', '{\"code\":0,\"data\":true,\"msg\":\"操作成功\"}', 0, NULL, '2026-04-01 22:45:43');
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`) VALUES (1101, '商品', 2, 'com.cloud.cms.controller.backed.CmsProductController.edit()', 'PUT', 1, 'admin', NULL, '/product', '127.0.0.1', '', '{\"description\":\"《红楼梦》以贾、史、王、薛四大家族的兴衰为背景，以富贵公子贾宝玉为视角，以贾宝玉与林黛玉、薛宝钗的爱情婚姻悲剧为主线，描绘了一些闺阁佳人的人生百态，展现了真正的人性美和悲剧美，是一部从各个角度展现女性美以及中国古代社会百态的史诗性著作。\",\"productStatus\":1,\"updateTime\":1775054808372,\"createTime\":1744387200000,\"price\":37.9,\"imageUrl\":\"http://118.196.16.103:9000/cloud/2026/04/01/红楼梦_20260401224643A012.jpg\",\"name\":\"红楼梦\",\"id\":\"5059\",\"stock\":996,\"categoryId\":\"1015\"}', '{\"code\":0,\"data\":true,\"msg\":\"操作成功\"}', 0, NULL, '2026-04-01 22:46:46');
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`) VALUES (1102, '商品', 2, 'com.cloud.cms.controller.backed.CmsProductController.edit()', 'PUT', 1, 'admin', NULL, '/product', '127.0.0.1', '', '{\"description\":\"《三国演义》（又名《三国志演义》《三国志通俗演义》《第一才子书》 [22] [31]）是元末明初小说家罗贯中根据陈寿《三国志》裴松之注解、《后汉书》以及民间三国故事传说，经过艺术加工创作而成的长篇章回体历史演义小说。 [32]现存其最早刊本为明嘉靖壬午（1522）刊刻，在嘉靖本后，以它为底本的新刊本大量涌现。清康熙年间毛纶父子对该小说作了修改和评点，从此毛本长期流行于世。\",\"productStatus\":1,\"updateTime\":1775054894663,\"createTime\":1744387200000,\"price\":45.5,\"imageUrl\":\"http://118.196.16.103:9000/cloud/2026/04/01/三国演义_20260401224748A013.jpg\",\"name\":\"三国演义\",\"id\":\"5070\",\"stock\":296,\"categoryId\":\"1015\"}', '{\"code\":0,\"data\":true,\"msg\":\"操作成功\"}', 0, NULL, '2026-04-01 22:48:12');
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`) VALUES (1103, '商品', 2, 'com.cloud.cms.controller.backed.CmsProductController.edit()', 'PUT', 1, 'admin', NULL, '/product', '127.0.0.1', '', '{\"description\":\"《西游记》是中国神魔小说的经典之作，达到了古代长篇浪漫主义小说的巅峰，与《三国演义》《水浒传》《红楼梦》并称为中国古典四大名著。《西游记》自问世以来在民间广为流传，各式各样的版本层出不穷。明代刊本有六种，清代刊本、抄本也有七种，典籍所记已佚版本十三种。鸦片战争以后，大量中国古典文学作品被译为西文，《西游记》渐渐传入欧美，被译为英、法、德、意、西、手语、世（世界语）、斯（斯瓦希里语）、俄、捷、罗、波、日、朝、越等语言\",\"productStatus\":1,\"updateTime\":1775054977397,\"createTime\":1744387200000,\"price\":89.9,\"imageUrl\":\"http://118.196.16.103:9000/cloud/2026/04/01/西游记_20260401224935A014.jpg\",\"name\":\"西游记\",\"id\":\"5050\",\"stock\":150,\"categoryId\":\"1015\"}', '{\"code\":0,\"data\":true,\"msg\":\"操作成功\"}', 0, NULL, '2026-04-01 22:49:36');
